use vstd::prelude::*;

verus! {
    fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
        requires
            x.len() > 0, // The input array must be non-empty
        ensures
            result.len() == x.len(), // The output array must have the same length as the input
            forall |i: nat| 0 <= i < result.len() ==> 
                (i == 0 || i == (result.len() - 1) ==> result[i] == 0.5) && 
                (i > 0 && i < (result.len() - 1) ==> result[i] == 1.0), // Weights based on position
    {
        let n = x.len() as nat; // Get the length of the input array
        let mut result: Vec<f32> = vec![0.0; n as usize]; // Initialize the result array with zeros

        // Set the weights based on the specified conditions
        if n > 0 {
            result[0] = 0.5; // First index weight
        }
        if n > 1 {
            result[(n - 1) as usize] = 0.5; // Last index weight
        }
        
        // Fill in the weights for the middle indices
        for i in 1..(n - 1) {
            result[i as usize] = 1.0; // Middle indices weight
        }

        result // Return the result array
    }
}
